#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <algorithm>
#include <string>
#include <map>
#include <iostream>
using namespace std;
map<string, string> dict;
int main() {
    int N;
    cin >> N;
    while(N --) {
        string word1, word2;
        cin >> word1 >> word2;
        dict[word1] = word2;
    }
    string content, word = "";
    cin >> content, content += "\n";
    int m = content.length();
    for(int i = 0; i < m; i ++) {
        if (content[i] >= 'a' && content[i] <= 'z')
            word += content[i];
        else {
            if (word != "") {
                if (dict.count(word))
                    cout << dict[word];
                else cout << "UNK";
                word = "";
            }
            cout << content[i];
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 100005;
int a[N], t;
int b[N], h;
int n;
int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i) {
        scanf("%d", &a[i]);
    }
    for (int i = 1; i <= n; ++i) {
        scanf("%d", &b[i]);
    }
    h = 1;
    t = 0;
    sort(a + 1, a + n + 1);
    sort(b + 1, b + n + 1);
    int ans = 0;
    for (int i = 1; i <= n; ++i)
        if (a[i] > b[h])
            ++ans, ++h;
    printf("%d\n", ans);
    return 0;
}
